namespace sv_daca38ae8f654a11b5255a9cd1d76a16.Client.Services;

public sealed record Shipment(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> Updates);

public sealed record StatusUpdate(
    DateTimeOffset Timestamp,
    string Description,
    string Location);

namespace sv_daca38ae8f654a11b5255a9cd1d76a16.Client.Services;

public interface IShipmentService
{
    Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using sv_daca38ae8f654a11b5255a9cd1d76a16.Client.Services;

namespace sv_daca38ae8f654a11b5255a9cd1d76a16.Services;

public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new Shipment(
            "PKG-001",
            "In Transit",
            "Chicago, IL",
            new DateTimeOffset(2026, 7, 7, 17, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new(new DateTimeOffset(2026, 7, 1, 8, 0, 0, TimeSpan.Zero), "Package picked up", "New York, NY"),
                new(new DateTimeOffset(2026, 7, 2, 14, 30, 0, TimeSpan.Zero), "Arrived at sorting facility", "Philadelphia, PA"),
                new(new DateTimeOffset(2026, 7, 3, 6, 15, 0, TimeSpan.Zero), "In transit to destination", "Chicago, IL"),
            }),

        ["PKG-002"] = new Shipment(
            "PKG-002",
            "Delivered",
            "San Francisco, CA",
            new DateTimeOffset(2026, 7, 2, 12, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new(new DateTimeOffset(2026, 6, 28, 9, 0, 0, TimeSpan.Zero), "Package picked up", "Seattle, WA"),
                new(new DateTimeOffset(2026, 6, 29, 11, 0, 0, TimeSpan.Zero), "Arrived at regional hub", "Portland, OR"),
                new(new DateTimeOffset(2026, 7, 1, 16, 45, 0, TimeSpan.Zero), "Out for delivery", "San Francisco, CA"),
                new(new DateTimeOffset(2026, 7, 2, 10, 20, 0, TimeSpan.Zero), "Delivered", "San Francisco, CA"),
            }),

        ["PKG-003"] = new Shipment(
            "PKG-003",
            "Processing",
            "Dallas, TX",
            new DateTimeOffset(2026, 7, 10, 18, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new(new DateTimeOffset(2026, 7, 3, 7, 0, 0, TimeSpan.Zero), "Label created", "Dallas, TX"),
            }),
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate slow backend
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

using System.Net.Http.Json;

namespace sv_daca38ae8f654a11b5255a9cd1d76a16.Client.Services;

/// <summary>
/// HTTP-based implementation used when running on WebAssembly.
/// </summary>
public sealed class ShipmentServiceClient : IShipmentService
{
    private readonly HttpClient _http;

    public ShipmentServiceClient(HttpClient http)
    {
        _http = http;
    }

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await _http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
            return null;

        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<Shipment>(ct);
    }
}

using sv_daca38ae8f654a11b5255a9cd1d76a16.Client.Services;

namespace sv_daca38ae8f654a11b5255a9cd1d76a16;

public static class ShipmentsApi
{
    public static void MapShipmentsApi(this WebApplication app)
    {
        app.MapGet("api/shipments/{trackingNumber}", async (
            string trackingNumber,
            IShipmentService service,
            CancellationToken ct) =>
        {
            var shipment = await service.GetShipmentAsync(trackingNumber, ct);
            return shipment is null ? Results.NotFound() : Results.Ok(shipment);
        });
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_daca38ae8f654a11b5255a9cd1d76a16.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (_loading)
{
    <div class="loading-placeholder">
        <p>Loading shipment details for <strong>@TrackingNumber</strong>...</p>
    </div>
}
else if (_error is not null)
{
    <div class="error-message">
        <p>@_error</p>
        <button @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is null)
{
    <div class="not-found">
        <p>No shipment found for tracking number <strong>@TrackingNumber</strong>.</p>
    </div>
}
else
{
    <div class="shipment-details">
        <h2>Shipment @_shipment.TrackingNumber</h2>
        <dl>
            <dt>Status</dt>
            <dd>@_shipment.Status</dd>
            <dt>Location</dt>
            <dd>@_shipment.Location</dd>
            <dt>Estimated Delivery</dt>
            <dd>@_shipment.EstimatedDelivery.ToString("f")</dd>
        </dl>

        <h3>Status Updates</h3>
        <ul class="status-updates">
            @foreach (var update in _shipment.Updates)
            {
                <li>
                    <time datetime="@update.Timestamp.ToString("o")">@update.Timestamp.ToString("g")</time>
                    &mdash; @update.Description (@update.Location)
                </li>
            }
        </ul>
    </div>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = string.Empty;

    private Shipment? _shipment;
    private bool _loading;
    private string? _error;

    private CancellationTokenSource? _cts;

    protected override async Task OnParametersSetAsync()
    {
        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        _loading = true;
        _error = null;
        _shipment = null;
        StateHasChanged();

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Navigation changed or component disposed — do nothing
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _error = "The request timed out. Please try again.";
        }
        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _error = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _error = "Something went wrong while loading the shipment. Please try again.";
        }
        finally
        {
            _loading = false;
            StateHasChanged();
        }
    }

    private async Task RetryAsync()
    {
        await LoadShipmentAsync();
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

